package com.aerosensei.entity;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.UUID;

@Entity
@Table(name = "sensor_registry")
public class SensorRegistry {

    // In your SQL, sensor_id is the PRIMARY KEY, so it gets the @Id annotation
    @Id
    @Column(name = "sensor_id", length = 50)
    private String sensorId;

    // UUID generated by PostgreSQL
    @Column(name = "id", insertable = false, updatable = false)
    private UUID id;

    // This creates the Foreign Key link to the Company entity!
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "company_id")
    private Company company;

    @Column(name = "location_name", length = 100, nullable = false)
    private String locationName;

    @Column(nullable = false, precision = 11, scale = 8)
    private BigDecimal latitude;

    @Column(nullable = false, precision = 11, scale = 8)
    private BigDecimal longitude;

    @Column(length = 20)
    private String status;

    @Column(name = "installation_date")
    private LocalDate installationDate;

    // Matches the DEFAULT CURRENT_TIMESTAMP in your SQL
    @Column(name = "created_at", insertable = false, updatable = false)
    private LocalDateTime createdAt;


    // Default Constructor
    public SensorRegistry() {}

    // --- Getters and Setters ---
    public String getSensorId() { return sensorId; }
    public void setSensorId(String sensorId) { this.sensorId = sensorId; }

    public UUID getId() { return id; }
    // No setter for ID since PostgreSQL generates it

    public Company getCompany() { return company; }
    public void setCompany(Company company) { this.company = company; }

    public String getLocationName() { return locationName; }
    public void setLocationName(String locationName) { this.locationName = locationName; }

    public BigDecimal getLatitude() { return latitude; }
    public void setLatitude(BigDecimal latitude) { this.latitude = latitude; }

    public BigDecimal getLongitude() { return longitude; }
    public void setLongitude(BigDecimal longitude) { this.longitude = longitude; }

    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }

    public LocalDate getInstallationDate() { return installationDate; }
    public void setInstallationDate(LocalDate installationDate) { this.installationDate = installationDate; }

    public LocalDateTime getCreatedAt() { return createdAt; }
}